    try:
        fn(o); print(fn.__name__, 'ok')
    except Exception as e:
        print(fn.__name__, type(e).__name__, e)
try:
    pickle.loads(pickle.dumps(o)); print('pickle ok')
except Exception as e:
    print('pickle', type(e).__name__, e)
